import { test, expect, Page } from '@playwright/test';

test.describe('Session Expiration', () => {
  let page: Page;

  test.beforeEach(async ({ browser }) => {
    page = await browser.newPage();
    await page.goto('http://localhost:3000');
  });

  test('should display session expired message when token times out', async () => {
    // Login with valid credentials
    await page.getByLabel('Email').fill('user@example.com');
    await page.getByLabel('Password').fill('password123');
    await page.getByRole('button', { name: /sign in/i }).click();

    // Wait for successful login
    await expect(page.getByText(/welcome/i)).toBeVisible();

    // Simulate token expiration by setting expired token in localStorage
    await page.evaluate(() => {
      localStorage.setItem('authToken', 'expired_token_' + Date.now());
      localStorage.setItem('tokenExpiry', String(Date.now() - 1000));
    });

    // Trigger an API call that will fail due to expired token
    await page.getByRole('button', { name: /fetch data/i }).click();

    // Verify session expired message is displayed
    const sessionExpiredMessage = page.getByText(/session expired/i);
    await expect(sessionExpiredMessage).toBeVisible();
    await expect(sessionExpiredMessage).toContainText(/session expired/i);
  });

  test('should redirect to login page after session expiration message', async () => {
    // Login with valid credentials
    await page.getByLabel('Email').fill('user@example.com');
    await page.getByLabel('Password').fill('password123');
    await page.getByRole('button', { name: /sign in/i }).click();

    // Wait for successful login
    await expect(page.getByText(/welcome/i)).toBeVisible();

    // Simulate token expiration
    await page.evaluate(() => {
      localStorage.setItem('authToken', 'expired_token_' + Date.now());
      localStorage.setItem('tokenExpiry', String(Date.now() - 1000));
    });

    // Trigger an API call
    await page.getByRole('button', { name: /fetch data/i }).click();

    // Wait for session expired message
    await expect(page.getByText(/session expired/i)).toBeVisible();

    // Click the login button or link in the session expired message
    await page.getByRole('button', { name: /log in again/i }).click();

    // Verify redirected to login page
    await expect(page.getByLabel('Email')).toBeVisible();
    await expect(page.getByLabel('Password')).toBeVisible();
    await expect(page.getByRole('button', { name: /sign in/i })).toBeVisible();
  });

  test('should clear user data from localStorage when session expires', async () => {
    // Login with valid credentials
    await page.getByLabel('Email').fill('user@example.com');
    await page.getByLabel('Password').fill('password123');
    await page.getByRole('button', { name: /sign in/i }).click();

    // Wait for successful login
    await expect(page.getByText(/welcome/i)).toBeVisible();

    // Verify user data is in localStorage
    const userDataBefore = await page.evaluate(() => localStorage.getItem('userData'));
    expect(userDataBefore).toBeTruthy();

    // Simulate token expiration
    await page.evaluate(() => {
      localStorage.setItem('authToken', 'expired_token_' + Date.now());
      localStorage.setItem('tokenExpiry', String(Date.now() - 1000));
    });

    // Trigger an API call
    await page.getByRole('button', { name: /fetch data/i }).click();

    // Wait for session expired message
    await expect(page.getByText(/session expired/i)).toBeVisible();

    // Verify sensitive data is cleared from localStorage
    const userDataAfter = await page.evaluate(() => localStorage.getItem('userData'));
    const authToken = await page.evaluate(() => localStorage.getItem('authToken'));

    expect(userDataAfter).toBeNull();
    expect(authToken).toBeNull();
  });

  test('should display session expired error with appropriate styling', async () => {
    // Login with valid credentials
    await page.getByLabel('Email').fill('user@example.com');
    await page.getByLabel('Password').fill('password123');
    await page.getByRole('button', { name: /sign in/i }).click();

    // Wait for successful login
    await expect(page.getByText(/welcome/i)).toBeVisible();

    // Simulate token expiration
    await page.evaluate(() => {
      localStorage.setItem('authToken', 'expired_token_' + Date.now());
      localStorage.setItem('tokenExpiry', String(Date.now() - 1000));
    });

    // Trigger an API call
    await page.getByRole('button', { name: /fetch data/i }).click();

    // Get the session expired message element
    const sessionExpiredAlert = page.getByRole('alert').filter({ hasText: /session expired/i });

    // Verify the alert is visible
    await expect(sessionExpiredAlert).toBeVisible();

    // Verify the alert has error styling (red background or error class)
    const alertElement = page.getByText(/session expired/i).first();
    const computedStyle = await alertElement.evaluate((el) => {
      return window.getComputedStyle(el.closest('[role="alert"]') || el).backgroundColor;
    });

    // Verify it has some styling applied (not transparent)
    expect(computedStyle).not.toBe('rgba(0, 0, 0, 0)');
  });
});
